{ arg out=0, freq=440, amp=0.1, gate=1, pan=0, attack=0.01, decay=0.8, sustain=0.5, release=1.5, cutoff=3000, rq=0.5, pulseWidth=0.2, vibratoRate=5, vibratoDepth=0.005, filterModDepth=2;
    var sig, env, filterEnv, vibrato;

    env = EnvGen.ar(
        Env.adsr(attack, decay, sustain, release, curve: -4),
        gate: gate,
        doneAction: 2
    );

    filterEnv = EnvGen.ar(
        Env.adsr(attack, decay * 1.5, sustain * 0.7, release * 1.5, curve: -4),
        gate: gate
    );

    vibrato = LFSin.kr(vibratoRate) * (freq * vibratoDepth);

    sig = Pulse.ar(freq + vibrato, pulseWidth);

    sig = LPF.ar(sig, cutoff + (filterEnv * cutoff * filterModDepth));

    sig = sig * env * amp;

    sig = Pan2.ar(sig, pan);

    Out.ar(out, sig);
}
